export default function Hero({ personal }: { personal: Personal }) {
  const initials = personal.name
    .split(" ")
    .map((n) => n[0])
    .join("")
    .toUpperCase();

  return (
    <section id="hero" style={{ position: "relative", overflow: "hidden" }}>
      {/* RetroGrid background */}
      <RetroGrid />

      <div className="hero">
        {/* Left — Content */}
        <div className="hero-content">
          <div className="hero-badge">
            <span className="badge-dot" />
            <span>Available for work</span>
          </div>

          <h1 className="hero-name">{personal.name}</h1>

          {/* MorphingText for title */}
          <h2 className="hero-title">
            <MorphingText
              texts={MORPH_TEXTS}
              morphDuration={1}
              cooldown={2.2}
            />
          </h2>

          <p className="hero-tagline">{personal.tagline}</p>

          <div className="hero-actions">
            <a href="#projects" className="btn btn-primary" id="btn-view-work">
              View My Work
            </a>
            <InteractiveHoverButton
              href={personal.resumeUrl}
              id="btn-resume"
            >
              Download CV
            </InteractiveHoverButton>
          </div>

          <SocialLinks social={personal.social} className="hero-socials" />
        </div>

        {/* Right — Avatar with OrbitingCircles */}
        <div className="hero-visual">
          <div className="avatar-wrap">
            <div className="avatar-ring" aria-hidden="true" />
            <div className="avatar-inner">
              {personal.avatar ? (
                <img src={personal.avatar} alt={personal.name} />
              ) : (
                <span>{initials}</span>
              )}
            </div>

            {/* Inner orbit — faster */}
            <OrbitingCircles iconSize={32} radius={148} duration={16} path>
              <TechIcons.React />
              <TechIcons.TypeScript />
              <TechIcons.Node />
              <TechIcons.Docker />
            </OrbitingCircles>

            {/* Outer orbit — reverse */}
            <OrbitingCircles iconSize={26} radius={186} duration={24} reverse path={false}>
              <TechIcons.Next />
              <TechIcons.Python />
              <TechIcons.AWS />
            </OrbitingCircles>
          </div>
        </div>

        {/* Scroll Indicator */}
        <div className="hero-scroll" aria-hidden="true">
          <span>Scroll</span>
          <div className="scroll-line" />
        </div>
      </div>
    </section>
  );
}
